//! Generated images fed back as input on Gemini: see `common/image_inputs.rs`.

use rig::providers::gemini;

use super::super::support::with_gemini_cassette;
use crate::image_inputs;

/// A vision model reads the generated bytes as user content.
#[tokio::test]
async fn generated_image_as_user_content() {
    const SCENARIO: &str = "image_input_matrix/generated_image_as_user_content";
    with_gemini_cassette(
        "image_input_matrix/generated_image_as_user_content",
        |client| async move {
            let bytes = image_inputs::generate(
                &client.image_generation(gemini::GEMINI_2_5_FLASH_IMAGE),
                None,
                None,
            )
            .await;
            image_inputs::as_user_content(
                &client.completion(gemini::completion::GEMINI_2_5_FLASH),
                &bytes,
                None,
            )
            .await;
        },
    )
    .await;
    image_inputs::assert_recorded("gemini", SCENARIO, image_inputs::Slot::UserContent);
}

/// A Gemini 3 model reads the generated bytes as a multimodal function
/// response (2.5 rejects images in function responses).
#[tokio::test]
async fn generated_image_as_tool_result() {
    const SCENARIO: &str = "image_input_matrix/generated_image_as_tool_result";
    with_gemini_cassette(
        "image_input_matrix/generated_image_as_tool_result",
        |client| async move {
            let bytes = image_inputs::generate(
                &client.image_generation(gemini::GEMINI_2_5_FLASH_IMAGE),
                None,
                None,
            )
            .await;
            image_inputs::as_tool_result(
                &client.completion(gemini::completion::GEMINI_3_FLASH_PREVIEW),
                &bytes,
                None,
            )
            .await;
        },
    )
    .await;
    image_inputs::assert_recorded("gemini", SCENARIO, image_inputs::Slot::ToolResult);
}
